// ======================================================
// METEO-RISK AI
// AI FLOOD EARLY WARNING
// FUNCTION : DATA + FLOOD RISK SCORE
// WEATHER + GEO + WATER LEVEL + WATER TREND
// ======================================================


// ------------------------------------------------------
// 1. NORMALISATION DES INPUTS
// ------------------------------------------------------

const items = Array.isArray(input) ? input : [input];


// Weather
const weatherResponse = items.find(
  item => item?.body?.current || item?.body?.hourly
);


// Geo
const geoResponse = items.find(
  item =>
    item?.body?.city ||
    item?.body?.locality ||
    item?.body?.location
);


// Water Sensor
const sensorResponse = items.find(
  item => item?.sensor?.type === "WATER_LEVEL"
);


// Extraction
const data = weatherResponse?.body || {};
const geo = geoResponse?.body || {};
const sensor = sensorResponse?.sensor || {};

const current = data.current || {};
const hourly = data.hourly || {};


// ------------------------------------------------------
// 2. LOCALISATION
// ------------------------------------------------------

const geoLocation = geo.location || {};

const location = {

  city:
    geo.city ||
    geo.locality ||
    geoLocation.city ||
    sensor.city ||
    "Casablanca",

  country:
    geo.countryName ||
    geoLocation.country ||
    "Morocco",

  country_code:
    geo.countryCode ||
    geoLocation.country_code ||
    "MA",

  region:
    geo.principalSubdivision ||
    geoLocation.region ||
    "Casablanca-Settat",

  latitude: Number(
    geo.latitude ??
    geoLocation.latitude ??
    data.latitude ??
    0
  ),

  longitude: Number(
    geo.longitude ??
    geoLocation.longitude ??
    data.longitude ??
    0
  ),

  timezone:
    data.timezone ||
    geo.timezone ||
    "Africa/Casablanca"
};


// ------------------------------------------------------
// 3. MÉTÉO ACTUELLE
// ------------------------------------------------------

const temperature = Number(
  current.temperature_2m ?? 0
);

const humidity = Number(
  current.relative_humidity_2m ?? 0
);

const precipitation = Number(
  current.precipitation ?? 0
);

const rain = Number(
  current.rain ?? 0
);

const wind = Number(
  current.wind_speed_10m ?? 0
);

const gust = Number(
  current.wind_gusts_10m ?? 0
);

const pressure = Number(
  current.pressure_msl ??
  current.surface_pressure ??
  1013
);

const timestamp =
  current.time ||
  new Date().toISOString();


// ------------------------------------------------------
// 4. WATER SENSOR
// ------------------------------------------------------

const waterLevel = Number(
  sensor.water_level_cm ?? 0
);

const previousWaterLevel = Number(
  sensor.previous_water_level_cm ??
  waterLevel
);

const warningLevel = Number(
  sensor.warning_level_cm ?? 70
);

const criticalLevel = Number(
  sensor.critical_level_cm ?? 90
);


// Rise rate
const riseRate = Number(
  sensor.rise_rate_cm ??
  (waterLevel - previousWaterLevel)
);


// Trend
const waterTrend =
  sensor.trend ||
  (
    riseRate >= 5
      ? "RISING_FAST"
      : riseRate > 0
        ? "RISING"
        : riseRate < 0
          ? "FALLING"
          : "STABLE"
  );


const sensorStatus =
  sensor.status || "UNKNOWN";


// ------------------------------------------------------
// 5. PRÉVISIONS
// ------------------------------------------------------

const hourlyPrecipitation =
  Array.isArray(hourly.precipitation)
    ? hourly.precipitation
    : [];

const hourlyRain =
  Array.isArray(hourly.rain)
    ? hourly.rain
    : [];

const hourlyProbability =
  Array.isArray(hourly.precipitation_probability)
    ? hourly.precipitation_probability
    : [];


// 6 prochaines heures disponibles
const nextHoursPrecipitation =
  hourlyPrecipitation
    .slice(0, 6)
    .reduce(
      (sum, value) =>
        sum + Number(value || 0),
      0
    );

const nextHoursRain =
  hourlyRain
    .slice(0, 6)
    .reduce(
      (sum, value) =>
        sum + Number(value || 0),
      0
    );

const maxRainProbability =
  hourlyProbability.length > 0
    ? Math.max(
        ...hourlyProbability
          .slice(0, 6)
          .map(value => Number(value || 0))
      )
    : 0;


// ------------------------------------------------------
// 6. INDICATEURS DE RISQUE
// ------------------------------------------------------

let currentRainRisk = 0;
let forecastRainRisk = 0;
let persistenceRisk = 0;

let waterLevelRisk = 0;
let waterTrendRisk = 0;

let humidityRisk = 0;
let pressureRisk = 0;
let windRisk = 0;


// ------------------------------------------------------
// 7. PLUIE ACTUELLE
// ------------------------------------------------------

const rainValue = Math.max(
  rain,
  precipitation
);

if (rainValue >= 30) {

  currentRainRisk = 100;

} else if (rainValue >= 20) {

  currentRainRisk = 90;

} else if (rainValue >= 10) {

  currentRainRisk = 70;

} else if (rainValue >= 5) {

  currentRainRisk = 45;

} else if (rainValue > 0) {

  currentRainRisk = 20;
}


// ------------------------------------------------------
// 8. PRÉVISIONS PLUIE
// ------------------------------------------------------

if (nextHoursPrecipitation >= 50) {

  forecastRainRisk = 100;

} else if (nextHoursPrecipitation >= 30) {

  forecastRainRisk = 85;

} else if (nextHoursPrecipitation >= 20) {

  forecastRainRisk = 70;

} else if (nextHoursPrecipitation >= 10) {

  forecastRainRisk = 50;

} else if (nextHoursPrecipitation >= 5) {

  forecastRainRisk = 30;
}


// ------------------------------------------------------
// 9. PERSISTANCE
// ------------------------------------------------------

if (
  rainValue > 0 &&
  nextHoursPrecipitation >= 20
) {

  persistenceRisk = 100;

} else if (
  rainValue > 0 &&
  nextHoursPrecipitation >= 10
) {

  persistenceRisk = 70;

} else if (
  rainValue > 0
) {

  persistenceRisk = 30;
}


// ------------------------------------------------------
// 10. WATER LEVEL RISK
// ------------------------------------------------------

if (waterLevel >= criticalLevel) {

  waterLevelRisk = 100;

} else if (waterLevel >= warningLevel) {

  waterLevelRisk = 75;

} else if (
  waterLevel >= warningLevel * 0.8
) {

  waterLevelRisk = 40;

} else {

  waterLevelRisk = 0;
}


// ------------------------------------------------------
// 11. WATER TREND RISK
// ------------------------------------------------------

if (waterTrend === "RISING_FAST") {

  waterTrendRisk = 100;

} else if (waterTrend === "RISING") {

  waterTrendRisk = 60;

} else if (waterTrend === "STABLE") {

  waterTrendRisk = 20;

} else if (waterTrend === "FALLING") {

  waterTrendRisk = 0;
}


// ------------------------------------------------------
// 12. HUMIDITÉ
// ------------------------------------------------------

if (humidity >= 95) {

  humidityRisk = 100;

} else if (humidity >= 90) {

  humidityRisk = 70;

} else if (humidity >= 80) {

  humidityRisk = 40;
}


// ------------------------------------------------------
// 13. PRESSION
// ------------------------------------------------------

if (pressure < 990) {

  pressureRisk = 100;

} else if (pressure < 1000) {

  pressureRisk = 70;

} else if (pressure < 1010) {

  pressureRisk = 40;
}


// ------------------------------------------------------
// 14. VENT
// ------------------------------------------------------

if (gust >= 90) {

  windRisk = 100;

} else if (gust >= 70) {

  windRisk = 75;

} else if (gust >= 50) {

  windRisk = 50;

} else if (gust >= 30) {

  windRisk = 25;
}


// ------------------------------------------------------
// 15. FLOOD RISK SCORE
// ------------------------------------------------------
//
// Pondération prototype:
//
// current rain      20%
// forecast rain     18%
// persistence       10%
// water level       32%
// water trend       12%
// humidity           3%
// pressure         2.5%
// wind             2.5%
//
// TOTAL = 100%
// ------------------------------------------------------

let riskScore = Math.round(

  currentRainRisk * 0.20 +

  forecastRainRisk * 0.18 +

  persistenceRisk * 0.10 +

  waterLevelRisk * 0.32 +

  waterTrendRisk * 0.12 +

  humidityRisk * 0.03 +

  pressureRisk * 0.025 +

  windRisk * 0.025

);


riskScore = Math.max(
  0,
  Math.min(100, riskScore)
);


// ------------------------------------------------------
// 16. NIVEAU DE RISQUE
// + RÈGLES DE SÉCURITÉ HYDROLOGIQUES
// ------------------------------------------------------

let riskLevel;

// CAS 1 : niveau critique + montée rapide
// Priorité maximale
if (
  waterLevel >= criticalLevel &&
  waterTrend === "RISING_FAST"
) {

  riskLevel = "CRITICAL";

}

// CAS 2 : niveau d'eau critique
// Minimum HIGH même sans pluie
else if (
  waterLevel >= criticalLevel
) {

  riskLevel = "HIGH";

}

// CAS 3 : niveau WARNING + montée rapide
else if (
  waterLevel >= warningLevel &&
  waterTrend === "RISING_FAST"
) {

  riskLevel = "HIGH";

}

// Sinon classification par score global
else if (riskScore >= 75) {

  riskLevel = "CRITICAL";

} else if (riskScore >= 50) {

  riskLevel = "HIGH";

} else if (riskScore >= 25) {

  riskLevel = "MEDIUM";

} else {

  riskLevel = "LOW";

}
// ------------------------------------------------------
// 17. RAISONS
// ------------------------------------------------------

const reasons = [];


// Rain
if (rainValue >= 20) {

  reasons.push(
    `Fortes précipitations actuelles : ${rainValue} mm`
  );

} else if (rainValue >= 10) {

  reasons.push(
    `Précipitations importantes : ${rainValue} mm`
  );

} else if (rainValue >= 5) {

  reasons.push(
    `Précipitations modérées : ${rainValue} mm`
  );
}


// Forecast
if (nextHoursPrecipitation >= 20) {

  reasons.push(
    `Précipitations prévues importantes dans les prochaines heures : ${nextHoursPrecipitation.toFixed(1)} mm`
  );
}


// Persistence
if (persistenceRisk >= 70) {

  reasons.push(
    "Persistance des précipitations détectée"
  );
}


// Probability
if (maxRainProbability >= 70) {

  reasons.push(
    `Probabilité élevée de précipitations : ${maxRainProbability}%`
  );
}


// Water level
if (waterLevel >= criticalLevel) {

  reasons.push(
    `Niveau d'eau critique : ${waterLevel} cm`
  );

} else if (waterLevel >= warningLevel) {

  reasons.push(
    `Niveau d'eau élevé : ${waterLevel} cm`
  );

} else if (
  waterLevel >= warningLevel * 0.8
) {

  reasons.push(
    `Niveau d'eau à surveiller : ${waterLevel} cm`
  );
}


// Water trend
if (waterTrend === "RISING_FAST") {

  reasons.push(
    `Montée rapide du niveau d'eau : +${riseRate} cm`
  );

} else if (waterTrend === "RISING") {

  reasons.push(
    `Niveau d'eau en hausse : +${riseRate} cm`
  );
}


// Humidity
if (humidity >= 90) {

  reasons.push(
    `Humidité élevée : ${humidity}%`
  );
}


// Pressure
if (pressure < 1000) {

  reasons.push(
    `Pression atmosphérique basse : ${pressure} hPa`
  );
}


// Wind
if (gust >= 50) {

  reasons.push(
    `Rafales importantes : ${gust} km/h`
  );
}


// ------------------------------------------------------
// 18. ALERTE
// ------------------------------------------------------

const alert =
  riskLevel === "HIGH" ||
  riskLevel === "CRITICAL";


// ------------------------------------------------------
// 19. MESSAGE
// ------------------------------------------------------

let message;

if (riskLevel === "CRITICAL") {

  message =
    "ALERTE CRITIQUE : risque élevé d'inondation détecté. Une intervention immédiate est recommandée.";

} else if (riskLevel === "HIGH") {

  message =
    "ALERTE ÉLEVÉE : les conditions hydrologiques et météorologiques indiquent un risque important d'inondation.";

} else if (riskLevel === "MEDIUM") {

  message =
    "VIGILANCE : certains indicateurs météorologiques ou hydrologiques nécessitent une surveillance renforcée.";

} else {

  message =
    "Conditions actuellement normales. Aucun risque élevé d'inondation détecté.";
}


// ------------------------------------------------------
// 20. CONSEILS
// ------------------------------------------------------

const advice = [];

if (riskLevel === "CRITICAL") {

  advice.push(
    "Déclencher immédiatement le protocole d'alerte."
  );

  advice.push(
    "Informer les responsables et les équipes terrain."
  );

  advice.push(
    "Surveiller en continu le niveau d'eau."
  );

  advice.push(
    "Préparer les mesures d'évacuation si nécessaire."
  );

} else if (riskLevel === "HIGH") {

  advice.push(
    "Renforcer immédiatement la surveillance."
  );

  advice.push(
    "Surveiller l'évolution du niveau d'eau."
  );

  advice.push(
    "Préparer les équipes d'intervention."
  );

} else if (riskLevel === "MEDIUM") {

  advice.push(
    "Maintenir une surveillance météorologique et hydrologique renforcée."
  );

  advice.push(
    "Contrôler régulièrement le niveau d'eau."
  );

} else {

  advice.push(
    "Aucune action d'urgence recommandée."
  );
}


// ------------------------------------------------------
// 21. SORTIE FINALE
// ------------------------------------------------------

return {

  project: "METEO-RISK AI",

  system: "AI Flood Early Warning",

  location,

  timestamp,


  weather: {

    temperature_c:
      temperature,

    humidity_percent:
      humidity,

    precipitation_mm:
      precipitation,

    rain_mm:
      rain,

    wind_kmh:
      wind,

    wind_gust_kmh:
      gust,

    pressure_hpa:
      pressure
  },


  forecast: {

    next_6h_precipitation_mm:
      Number(
        nextHoursPrecipitation.toFixed(2)
      ),

    next_6h_rain_mm:
      Number(
        nextHoursRain.toFixed(2)
      ),

    max_precipitation_probability_percent:
      maxRainProbability
  },


  water_sensor: {

    sensor_id:
      sensor.sensor_id || "",

    type:
      sensor.type || "WATER_LEVEL",

    previous_water_level_cm:
      previousWaterLevel,

    water_level_cm:
      waterLevel,

    rise_rate_cm:
      riseRate,

    trend:
      waterTrend,

    warning_level_cm:
      warningLevel,

    critical_level_cm:
      criticalLevel,

    status:
      sensorStatus,

    timestamp:
      sensor.timestamp || null,

    data_source:
      sensor.data_source || "UNKNOWN"
  },


  risk: {

    score:
      riskScore,

    level:
      riskLevel,

    alert,

    message,

    reasons,

    indicators: {

      current_rain:
        currentRainRisk,

      forecast_rain:
        forecastRainRisk,

      persistence:
        persistenceRisk,

      water_level:
        waterLevelRisk,

      water_trend:
        waterTrendRisk,

      humidity:
        humidityRisk,

      pressure:
        pressureRisk,

      wind:
        windRisk
    }
  },


  advice
};

const data = input || {};

const risk = data.risk || {};
const sensor = data.water_sensor || {};

return {
  ...data,

  risk: {
    ...risk,
    level: "LOW",
    alert: false
  },

  low_management: {
    monitoring_required: true,
    recovery_check_required: true,
    water_level_cm: sensor.water_level_cm ?? null,
    trend: sensor.trend || "UNKNOWN"
  },

  message:
    "Conditions de risque faible détectées. Surveillance normale. Si un incident est actif, vérifier les conditions de récupération avant clôture.",

  status: "LOW_RISK_MONITORING"
};

// ========================================
// METEO-RISK AI
// ALERT MANAGER
// ========================================

const data = input || {};

const risk = data.risk || {};
const action = data.action || {};
const location = data.location || {};

const level = risk.level || "LOW";
const score = Number(risk.score || 0);

let notificationRequired = false;
let emergency = false;
let priority = "NORMAL";
let channel = "NONE";
let actionRequired = false;


// ========================================
// DECISION SELON LE NIVEAU
// ========================================

if (level === "LOW") {

  notificationRequired = false;
  emergency = false;
  priority = "NORMAL";
  channel = "NONE";
  actionRequired = false;

} else if (level === "MEDIUM") {

  notificationRequired = true;
  emergency = false;
  priority = "MEDIUM";
  channel = "MONITORING";
  actionRequired = false;

} else if (level === "HIGH") {

  notificationRequired = true;
  emergency = false;
  priority = "HIGH";
  channel = "ALERT";
  actionRequired = true;

} else if (level === "CRITICAL") {

  notificationRequired = true;
  emergency = true;
  priority = "URGENT";
  channel = "EMERGENCY";
  actionRequired = true;
}


// ========================================
// OUTPUT
// ========================================

return {

  // IMPORTANT :
  // conserve toutes les données précédentes
  ...data,

  project:
    data.project || "METEO-RISK AI",

  system:
    data.system || "AI Flood Early Warning",

  location,

  timestamp:
    data.timestamp ||
    new Date().toISOString(),


  // Garde tout le risk original
  risk: {
    ...risk,

    score,

    level,

    alert:
      level === "HIGH" ||
      level === "CRITICAL"
  },


  alert_management: {

    notification_required:
      notificationRequired,

    emergency,

    priority,

    channel,

    action_required:
      actionRequired
  },


  // Prend le message déjà créé par Function_Data_Risk
  message:
    data.message ||
    risk.message ||
    "Aucune alerte particulière.",


  // Garde les recommandations / advice
  recommendations:
    Array.isArray(data.recommendations)
      ? data.recommendations
      : Array.isArray(data.advice)
        ? data.advice
        : [],


  status:
    emergency
      ? "EMERGENCY"
      : actionRequired
        ? "ACTION_REQUIRED"
        : notificationRequired
          ? "MONITORING_ALERT"
          : "NORMAL_MONITORING"
};

// ========================================
// METEO-RISK AI
// CREATE ALERT MESSAGE
// ========================================

const data = input || {};

const risk = data.risk || {};
const location = data.location || {};
const alert = data.alert_management || {};

const city = location.city || "Localisation inconnue";
const country = location.country || "Maroc";

const level = risk.level || "UNKNOWN";
const score = Number(risk.score || 0);

let title = "";
let emoji = "";
let action = "";

if (level === "MEDIUM") {
  emoji = "🟡";
  title = "VIGILANCE MÉTÉO";
  action = "Renforcer la surveillance des zones sensibles.";
}

if (level === "HIGH") {
  emoji = "🟠";
  title = "ALERTE MÉTÉO ÉLEVÉE";
  action = "Préparer les équipes et renforcer la surveillance.";
}

if (level === "CRITICAL") {
  emoji = "🔴";
  title = "ALERTE MÉTÉO CRITIQUE";
  action = "Intervention immédiate recommandée.";
}

const recommendations = Array.isArray(data.recommendations)
  ? data.recommendations
  : [];

const recommendationText = recommendations.length > 0
  ? recommendations.map((item, index) => `${index + 1}. ${item}`).join("\n")
  : "Aucune recommandation supplémentaire.";

const message = `
${emoji} <b>METEO-RISK AI — ${title}</b><br><br>

📍 <b>Localisation :</b> ${city}, ${country}<br>
🌍 <b>Région :</b> ${location.region || "Non renseignée"}<br>
🧭 <b>Latitude :</b> ${location.latitude ?? "N/A"}<br>
🧭 <b>Longitude :</b> ${location.longitude ?? "N/A"}<br><br>

⚠️ <b>Niveau de risque :</b> ${level}<br>
📊 <b>Score :</b> ${score}/100<br>
🚨 <b>Priorité :</b> ${alert.priority || "NORMAL"}<br>
📡 <b>Canal :</b> ${alert.channel || "ALERT"}<br><br>

💬 <b>Message :</b><br>
${data.message || "Aucun message disponible."}<br><br>

🎯 <b>Action recommandée :</b><br>
${action}<br><br>

📋 <b>Recommandations :</b><br>
${recommendations
  .map((item, index) => `${index + 1}. ${item}`)
  .join("<br>")}
`;
const subject = `METEO-RISK AI — ALERTE ${level}`;

return {
  project: "METEO-RISK AI",

  location,

  timestamp:
    data.timestamp ||
    new Date().toISOString(),

  risk,

  alert_management: alert,

  notification: {
    required: true,
    priority: alert.priority || "NORMAL",
    channel: alert.channel || "ALERT"
  },
  subject,

  message,

  status: "ALERT_MESSAGE_READY"
};

// ========================================
// METEO-RISK AI
// CREATE INCIDENT
// ========================================

const data = input || {};

const risk = data.risk || {};
const location = data.location || {};
const alertManagement = data.alert_management || {};

const now = new Date().toISOString();

// ========================================
// INCIDENT ID
// ========================================

const incidentId = `INC-${Date.now()}`;

// ========================================
// INCIDENT TYPE
// ========================================

let incidentType = "WEATHER_RISK";

if (risk.level === "HIGH") {
  incidentType = "FLOOD_RISK_ALERT";
}

if (risk.level === "CRITICAL") {
  incidentType = "FLOOD_EMERGENCY";
}

// ========================================
// PRIORITY
// ========================================

let priority = alertManagement.priority || "NORMAL";

if (risk.level === "HIGH") {
  priority = "HIGH";
}

if (risk.level === "CRITICAL") {
  priority = "URGENT";
}

// ========================================
// INTERVENTION REQUIRED
// ========================================

const interventionRequired =
  risk.level === "HIGH" ||
  risk.level === "CRITICAL";

// ========================================
// OUTPUT
// ========================================

return {
  project: data.project || "METEO-RISK AI",

  incident: {
    incident_id: incidentId,
    type: incidentType,
    created_at: now,
    status: "OPEN",
    severity: risk.level || "UNKNOWN",
    priority: priority,
    intervention_required: interventionRequired
  },

  location: {
    city: location.city || "",
    country: location.country || "",
    country_code: location.country_code || "",
    region: location.region || "",
    latitude: Number(location.latitude || 0),
    longitude: Number(location.longitude || 0),
    timezone: location.timezone || "Africa/Casablanca"
  },

  risk: {
    score: Number(risk.score || 0),
    level: risk.level || "UNKNOWN",
    alert: Boolean(risk.alert)
  },

  alert_management: alertManagement,

  message: data.message || "",

  recommendations:
    Array.isArray(data.recommendations)
      ? data.recommendations
      : [],

  timestamp:
    data.timestamp || now,

  status: "INCIDENT_OPEN"
};

// ========================================
// METEO-RISK AI
// ASSIGN INTERVENTION
// ========================================

const data = input || {};

const incident = data.incident || {};
const risk = data.risk || {};
const location = data.location || {};

const now = new Date().toISOString();

// ========================================
// ÉQUIPE ET TYPE D'ACTION
// ========================================

let team = "Monitoring Team";
let action = "MONITORING";
let responseTime = "STANDARD";

if (risk.level === "HIGH") {
  team = "Flood Response Team";
  action = "PREPARE_INTERVENTION";
  responseTime = "30_MINUTES";
}

if (risk.level === "CRITICAL") {
  team = "Emergency Response Team";
  action = "IMMEDIATE_INTERVENTION";
  responseTime = "IMMEDIATE";
}

// ========================================
// SORTIE
// ========================================

return {
  ...data,

  incident: {
    ...incident,
    status: "ASSIGNED"
  },

  intervention: {
    required: true,
    assigned_at: now,

    team: team,

    action: action,

    response_time: responseTime,

    location: {
      city: location.city || "",
      region: location.region || "",
      latitude: Number(location.latitude || 0),
      longitude: Number(location.longitude || 0)
    },

    status: "PENDING_INTERVENTION"
  },

  status: "INTERVENTION_ASSIGNED"
};

const data = input || {};

const incident = data.incident || {};
const intervention = data.intervention || {};

const now = new Date().toISOString();

return {
  ...data,

  incident: {
    ...incident,
    status: "COMPLETED"
  },

  intervention: {
    ...intervention,
    status: "COMPLETED",
    completed_at: now
  },

