function escapeHtml(text) {
  return String(text)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function reportToHtml(markdown) {

  return escapeHtml(markdown)
    .split("\n")
    .map(line => {

      const text = line.trim();

      if (!text) {
        return `<div style="height:10px;"></div>`;
      }

      // TITLE
      if (text.startsWith("# ")) {

        return `
          <h2 style="
            color:#0d47a1;
            margin:20px 0 15px 0;
          ">
            ${text.substring(2)}
          </h2>
        `;
      }

      // SECTION
      if (text.startsWith("## ")) {

        return `
          <h3 style="
            color:#1565c0;
            margin:22px 0 10px 0;
            border-bottom:1px solid #dddddd;
            padding-bottom:6px;
          ">
            ${text.substring(3)}
